const KB=window.KBBI||{};
const ROUTE=KB.route||"home";
const TALENTS=((KB.data&&KB.data.talents)||[]).map(x=>Object.assign({works:[],samples:[],videos:[],tags:[],voice:[],skills:[],clients:[],community:[]},x));

function initLang(){
  const q=new URLSearchParams(location.search).get("lang");if(q&&I18N[q])return q;
  try{const s=localStorage.getItem("kbbi-lang");if(s&&I18N[s])return s}catch(e){/* storage blocked: fall back to browser language */}
  const n=(navigator.language||"").toLowerCase();
  if(n.startsWith("zh"))return "zh";
  if(n.startsWith("id")||n.startsWith("ms"))return "id";
  return "en";
}
let lang=initLang(),tagFilter="all",catFilter="all";

const t=k=>I18N[lang][k];
const L=o=>o==null?"":typeof o==="string"?o:(o[lang]||o.id||"");
const esc=s=>String(s==null?"":s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const safeUrl=u=>/^https?:\/\//i.test(String(u||""))?String(u):"#";
const cssUrl=u=>safeUrl(u).replace(/["'()\\\s]/g,c=>encodeURIComponent(c));
const titleOf=w=>lang==="zh"&&w.orig?w.orig:L(w.title);
const castOrder={main:0,support:1,extra:2};
const talentHref=x=>"/talent/"+encodeURIComponent(x.slug)+"/";
const initials=n=>String(n).split(" ").map(s=>s[0]).join("").slice(0,2).toUpperCase();

