/* ---- media: links pasted in the sheet become embedded players ---- */
const PLAT={youtube:{n:"YouTube",f:"h"},tiktok:{n:"TikTok",f:"v"},instagram:{n:"Instagram",f:"v"},drive:{n:"Google Drive",f:"h"},link:{n:"Link",f:"h"}};
function mediaOf(url){
  url=String(url||"");let m;
  if((m=url.match(/(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/|embed\/)|youtu\.be\/)([\w-]{11})/))){const s=url.match(/[?&]t=(\d+)/);return{p:"youtube",id:m[1],embed:"https://www.youtube-nocookie.com/embed/"+m[1]+"?autoplay=1"+(s?"&start="+s[1]:"")}}
  if((m=url.match(/drive\.google\.com\/(?:file\/d\/|open\?id=)([\w-]+)/)))return{p:"drive",id:m[1],embed:"https://drive.google.com/file/d/"+m[1]+"/preview"};
  if((m=url.match(/tiktok\.com\/.*\/video\/(\d+)/)))return{p:"tiktok",id:m[1],embed:"https://www.tiktok.com/player/v1/"+m[1]};
  if((m=url.match(/instagram\.com\/(?:reel|reels|p)\/([\w-]+)/)))return{p:"instagram",id:m[1],embed:"https://www.instagram.com/reel/"+m[1]+"/embed"};
  return null;
}
function openPlayer(title,frame,url,label,wide){
  const d=document.getElementById("player");d.classList.toggle("wide",!!wide);
  d.innerHTML=`<div class="pl-head"><b>${esc(title)}</b><button type="button" class="pl-close" data-close>${t("close")} ✕</button></div>
   ${frame}<div class="pl-foot"><a class="btn sm" href="${esc(safeUrl(url))}" target="_blank" rel="noopener">${esc(label)}</a></div>`;
  try{d.showModal()}catch(e){d.setAttribute("open","")}
}
function openMedia(title,url){
  const m=mediaOf(url);
  if(!m){window.open(safeUrl(url),"_blank","noopener");return}
  const p=PLAT[m.p];
  openPlayer(title,`<div class="frame ${p.f} live"><iframe src="${esc(m.embed)}" title="${esc(title)}" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen></iframe></div>`,url,t("openOn").replace("{p}",p.n),p.f==="h");
}
function closePlayer(){const d=document.getElementById("player");d.innerHTML="";d.close?d.close():d.removeAttribute("open")}
function miniWave(seed){let s="";for(let i=0;i<48;i++){const h=20+Math.abs(Math.sin((i+seed*7)*.6)*Math.cos(i*.23+seed))*80;s+=`<i style="height:${h.toFixed(0)}%"></i>`}return s}
function wave(){let s="";for(let i=0;i<44;i++){const h=18+Math.abs(Math.sin(i*.55)*Math.cos(i*.21))*82+((i*37)%11);s+=`<span style="height:${Math.min(100,h).toFixed(0)}%;animation-delay:${(i%9)*-.18}s"></span>`}return s}
const bgImg=u=>u?`background-image:url(${cssUrl(u)});background-size:cover;background-position:center`:"";
const avatar=x=>x.photo?`<span class="avatar" style="${bgImg(x.photo)}" role="img" aria-label="${esc(x.name)}"></span>`:`<span class="mono">${esc(initials(x.name))}</span>`;

/* ---- shared blocks ---- */
function talentCard(x){
  return `<a class="tcard" href="${talentHref(x)}">
   <div class="tphoto">${avatar(x)}</div>
   <div class="tbody"><h3>${esc(x.name)}</h3><p>${esc(L(x.tagline))}</p>
    <div class="chips">${x.tags.map(g=>`<span class="chip">${esc(L(g))}</span>`).join("")}</div>
    <div class="meta">${x.works.length?x.works.length+" "+t("works"):"@"+esc(x.ig)}</div></div></a>`;
}
function rosterBlock(){
  if(!TALENTS.length)return `<div class="empty">${t("noTalents")}</div>`;
  const used=[];TALENTS.forEach(x=>x.tags.forEach(g=>{if(!used.some(u=>u.k===g.k))used.push(g)}));
  const list=TALENTS.filter(x=>tagFilter==="all"||x.tags.some(g=>g.k===tagFilter));
  return `<div class="chips" role="group" aria-label="Filter">
    <button type="button" class="filter" data-tag="all" aria-pressed="${tagFilter==="all"}">${t("filterAll")}</button>
    ${used.map(g=>`<button type="button" class="filter" data-tag="${esc(g.k)}" aria-pressed="${tagFilter===g.k}">${esc(L(g))}</button>`).join("")}
  </div>
  <div class="roster">${list.length?list.map(talentCard).join(""):`<div class="empty">${t("noMatch")}</div>`}</div>`;
}
function directBlock(){
  return `<section class="band"><div class="wrap"><div class="contact">
   <div><h2>${t("homeCtH")}</h2><p>${t("homeCtP")}</p></div>
   <div class="box"><a class="btn primary" href="/#talents">${t("homeCtBtn")}</a><span class="note">${t("ctNote")}</span></div>
  </div></div></section>`;
}
function contactBlock(x){
  const ig=encodeURIComponent(x.ig||"");
  const box=x.ig?`<a class="btn primary" href="https://ig.me/m/${ig}" target="_blank" rel="noopener">${ICON.ig}${t("ctBtn")} @${esc(x.ig)}</a>
    <div class="handle"><code>@${esc(x.ig)}</code><button type="button" data-copy="@${esc(x.ig)}">${t("ctCopy")}</button></div>`
    :`<div class="handle"><code>${t("ctNoIg")}</code></div>`;
  return `<section class="band" id="contact"><div class="wrap"><div class="contact">
   <div><div class="eyebrow" style="color:var(--sun)">${esc(x.name)}</div><h2 style="margin-top:6px">${t("ctH")}</h2>
    <p>${t("ctP")}</p><ul><li>${t("ct1")}</li><li>${t("ct2")}</li><li>${t("ct3")}</li></ul></div>
   <div class="box">${box}<span class="note">${t("ctNote")}</span></div>
  </div></div></section>`;
}

/* ---- views ---- */
function viewHome(){
  const works=TALENTS.flatMap(x=>x.works);
  return `<section class="hero"><div class="wrap">
    <div><div class="eyebrow">${t("heroEye")}</div><h1>${t("heroH")}</h1><p class="lead">${t("heroP")}</p>
     <div class="ctas"><a class="btn primary" href="/#talents">${t("ctaTalents")}</a><a class="btn" href="/#how">${t("ctaHow")}</a></div></div>
    <div class="booth" aria-hidden="true"><div class="booth-head"><span>${t("boothL")}</span><span class="onair"><i></i>${t("recording")}</span></div>
     <div class="wave">${wave()}</div>
     <div class="booth-stats"><div><b>${TALENTS.length}</b><span>${t("stTalent")}</span></div><div><b>${works.length}</b><span>${t("stTitles")}</span></div><div><b>3</b><span>${t("stLang")}</span></div></div></div>
  </div></section>
  <section class="band alt"><div class="wrap"><div class="sec-head"><div><div class="eyebrow">${t("svcEye")}</div><h2>${t("svcH")}</h2></div></div>
   <div class="services">${Object.keys(CATS).map(c=>`<div class="svc"><b>${L(CATS[c])}</b><span>${t("svcDesc")[c]}</span><span class="n">${works.filter(w=>w.cat===c).length} ${t("titles")}</span></div>`).join("")}</div></div></section>
  <section class="band" id="talents"><div class="wrap"><div class="sec-head"><div><div class="eyebrow">${t("rosEye")}</div><h2>${t("rosH")}</h2></div></div>
   <div id="roster">${rosterBlock()}</div></div></section>
  <section class="band alt" id="how"><div class="wrap"><div class="sec-head"><div><div class="eyebrow">${t("howEye")}</div><h2>${t("howH")}</h2></div></div>
   <div class="steps"><div class="step"><b>${t("how1b")}</b><p>${t("how1p")}</p></div><div class="step"><b>${t("how2b")}</b><p>${t("how2p")}</p></div><div class="step"><b>${t("how3b")}</b><p>${t("how3p")}</p></div></div></div></section>
  ${directBlock()}`;
}
function viewNotFound(){
  return `<section class="band"><div class="wrap"><div class="eyebrow">404</div><h2 class="sec-title">${t("nfH")}</h2><p class="muted">${t("nfP")}</p>
   <p style="margin-top:20px"><a class="btn primary" href="/">${t("nfBtn")}</a></p></div></section>`;
}
function workCard(w,k){
  const thumb=w.img?`<div class="thumb" style="${bgImg(w.img)}" role="img" aria-label="${esc(titleOf(w))}"></div>`
    :`<div class="thumb gen"><span>${esc(L(CATS[w.cat]))}</span></div>`;
  const orig=lang!=="zh"&&w.orig?`<div class="orig" lang="zh">${esc(w.orig)}</div>`:"";
  let watch="";
  if(w.link)watch=mediaOf(w.link)?`<button type="button" class="watch" data-work="${k}">${t("watch").replace(" ↗"," ▶")}</button>`:`<a class="watch" href="${esc(safeUrl(w.link))}" target="_blank" rel="noopener">${t("watch")}</a>`;
  return `<article class="pcard">${thumb}
   <div><div class="cat">${esc(L(CATS[w.cat]))}${w.platform?` · ${esc(w.platform)}`:""}</div>
   <h3>${esc(titleOf(w))}</h3>${orig}${w.note?`<div class="orig">${esc(L(w.note))}</div>`:""}</div>
   <div class="role"><span>${t("role")}:</span> ${esc(L(w.role))}</div>
   ${w.cast&&CAST[w.cast]?`<span class="cast ${w.cast}">${esc(L(CAST[w.cast]))}</span>`:""}
   ${watch}</article>`;
}
function portfolioBlock(x){
  if(!x.works.length)return `<div class="empty">${t("pfEmpty")}</div>`;
  const cats=Object.keys(CATS).filter(c=>x.works.some(w=>w.cat===c));
  if(catFilter!=="all"&&!cats.includes(catFilter))catFilter="all";
  const list=x.works.filter(w=>catFilter==="all"||w.cat===catFilter).sort((a,b)=>(castOrder[a.cast]??3)-(castOrder[b.cast]??3));
  return `<div class="tabs" role="group" aria-label="${t("pfEye")}">
    <button type="button" class="filter" data-cat="all" aria-pressed="${catFilter==="all"}">${t("filterAll")}<b>${x.works.length}</b></button>
    ${cats.map(c=>`<button type="button" class="filter" data-cat="${c}" aria-pressed="${catFilter===c}">${L(CATS[c])}<b>${x.works.filter(w=>w.cat===c).length}</b></button>`).join("")}
  </div><div class="pgrid">${list.map(w=>workCard(w,x.works.indexOf(w))).join("")}</div>`;
}
function demoBlock(x){
  if(!x.reel||!x.reel.url)return "";
  const m=mediaOf(x.reel.url);
  const th=m&&m.p==="youtube"?bgImg("https://i.ytimg.com/vi/"+m.id+"/hqdefault.jpg"):"";
  return `<section class="band" style="padding-bottom:0"><div class="wrap">
   <button type="button" class="reelcard" data-reel><div class="reelthumb" style="${th}"><span class="play">${ICON.play}</span></div>
   <div><div class="eyebrow">${t("demoEye")}</div><h3>${t("demoH")}</h3><p>${t("demoSub")}</p></div></button></div></section>`;
}
function aboutBlock(x){
  if(!x.voice.length&&!x.skills.length)return "";
  return `<section class="band" style="padding-bottom:0"><div class="wrap"><div class="eyebrow">${t("abEye")}</div><h2 class="sec-title">${t("abH")}</h2>
   <div class="about"><dl class="specs">${x.voice.map(f=>`<div><dt>${t(f.k)}</dt><dd>${esc(L(f.v))}</dd></div>`).join("")}</dl>
   ${x.skills.length?`<div class="sess" style="margin-top:0"><span class="lbl">${t("fSkill")}</span><div class="chips">${x.skills.map(k=>`<span class="chip">${esc(L(k))}</span>`).join("")}</div></div>`:""}</div></div></section>`;
}
function samplesBlock(x){
  if(!x.samples.length&&!x.samplesAll)return "";
  const rows=x.samples.map((s,i)=>`<div class="sample"><button type="button" class="play" data-sample="${i}" aria-label="${esc(s.raw?t("rawT"):L(s.title))}">${ICON.play}</button>
    <div style="min-width:0"><b>${s.raw?`<span class="raw">RAW</span>${t("rawT")}`:esc(L(s.title))}</b>${s.raw?`<small>${t("rawN")}</small>`:""}<div class="mini-wave" aria-hidden="true">${miniWave(i)}</div></div><span></span></div>`).join("");
  let all="";
  if(x.samplesAll){const u=x.samplesAll,p=/spreadsheets/.test(u)?"Google Sheet":/drive\.google/.test(u)?"Google Drive":"link";
    all=`<a class="sample-all" href="${esc(safeUrl(u))}" target="_blank" rel="noopener"><span class="ic">${ICON.drive}</span><span style="min-width:0"><b>${t("allSamples")}</b><small>${t("allSamplesSub").replace("{p}",p)}</small></span><span class="arrow" aria-hidden="true">↗</span></a>`}
  return `<section class="band" style="padding-bottom:0" id="samples"><div class="wrap"><div class="eyebrow">${t("vsEye")}</div><h2 class="sec-title">${t("vsH")}</h2>
   <div class="samples">${rows}${all}</div></div></section>`;
}
function videosBlock(x){
  if(!x.videos.length)return "";
  return `<section class="band" style="padding-bottom:0"><div class="wrap"><div class="eyebrow">${t("vidEye")}</div><h2 class="sec-title">${t("vidH")}</h2>
   <div class="vgrid">${x.videos.map((v,i)=>{const m=mediaOf(v.url),p=PLAT[m?m.p:"link"];
     const th=m&&m.p==="youtube"?bgImg("https://i.ytimg.com/vi/"+m.id+"/hqdefault.jpg"):"";
     return `<button type="button" class="vcard" data-video="${i}"><div class="vthumb" style="${th}"><span class="pf">${p.n}</span><span class="play">${ICON.play}</span></div><b>${t("video")} ${i+1}</b><small>${p.n}</small></button>`}).join("")}</div></div></section>`;
}
function credsBlock(x){
  if(!x.clients.length&&!x.community.length)return "";
  return `<section class="band" style="padding-bottom:0"><div class="wrap"><div class="eyebrow">${t("wwEye")}</div>
   <div class="creds">${x.clients.length?`<div><h2 class="sec-title">${t("wwH")}</h2><div class="logos">${x.clients.map(c=>`<span>${esc(c)}</span>`).join("")}</div></div>`:""}
   ${x.community.length?`<div><h2 class="sec-title">${t("comH")}</h2><div class="comm">${x.community.map(c=>`<div>${esc(c.n)}</div>`).join("")}</div></div>`:""}</div></div></section>`;
}
function studioBlock(x){
  const s=x.studio;if(!s)return "";
  const rows=[["gMic",s.mic],["gIf",s.iface],["gHp",s.hp],["gPc",s.pc],["gDaw",s.daw],["gRoom",s.room],["gAcc",s.acc],["gFile",s.file]]
    .filter(r=>Array.isArray(r[1])?r[1].length:r[1]);
  if(!rows.length&&!(s.session&&s.session.length)&&!s.sync)return "";
  const val=v=>Array.isArray(v)?v.map(esc).join("<br>"):esc(L(v));
  return `<section class="band" style="padding-bottom:0"><div class="wrap"><div class="eyebrow">${t("stEye")}</div><h2 class="sec-title">${t("stH")}</h2>
   <div class="studio${s.photo?"":" nophoto"}">
    ${s.photo?`<div class="booth-photo" role="img" aria-label="${t("stPhoto")}" style="${bgImg(s.photo)}"></div>`:""}
    <div><dl class="specs">${rows.map(([k,v])=>`<div><dt>${t(k)}</dt><dd>${val(v)}</dd></div>`).join("")}</dl>
     ${s.session&&s.session.length?`<div class="sess"><span class="lbl">${t("gSess")}</span><div class="chips">${s.session.map(n=>`<span class="chip">${esc(n)}</span>`).join("")}</div></div>`:""}
     ${s.sync?`<p class="sync"><i>✓</i>${t("syncYes")}</p>`:""}</div>
   </div></div></section>`;
}
function viewTalent(x){
  const cats=Object.keys(CATS).filter(c=>x.works.some(w=>w.cat===c));
  return `<div class="wrap"><a class="back" href="/#talents">${ICON.back}${t("back")}</a>
   <div class="profile"><div class="tphoto">${avatar(x)}</div>
    <div><div class="eyebrow">KBBI · ${t("brandSub")}</div><h1>${esc(x.name)}</h1><p class="tagline">${esc(L(x.tagline))}</p>
     ${x.avail?`<span class="avail"><i></i>${t("avail")}</span>`:""}
     ${x.bio?`<p class="bio">${esc(L(x.bio))}</p>`:""}
     <div class="chips">${x.tags.map(g=>`<span class="chip">${esc(L(g))}</span>`).join("")}</div>
     <div class="actions">${x.samples.length?`<button type="button" class="btn primary" data-scroll="samples">${ICON.drive}${t("listen")}</button>`:""}
      ${x.ig?`<a class="btn" href="https://www.instagram.com/${encodeURIComponent(x.ig)}/" target="_blank" rel="noopener">${ICON.ig}@${esc(x.ig)}</a>`:""}
      <button type="button" class="btn" data-copy="link">${ICON.link}${t("copy")}</button></div>
     ${cats.length?`<div class="counts">${cats.map(c=>`<div><b>${x.works.filter(w=>w.cat===c).length}</b><span>${L(CATS[c])}</span></div>`).join("")}</div>`:""}
    </div></div></div>
  ${demoBlock(x)}
  ${aboutBlock(x)}
  ${samplesBlock(x)}
  <section class="band" style="padding-bottom:0"><div class="wrap"><div class="eyebrow">${t("pfEye")}</div><h2 class="sec-title" style="font-size:clamp(28px,4vw,40px)">${t("pfH")}</h2>
   <div id="pf">${portfolioBlock(x)}</div></div></section>
  ${videosBlock(x)}
  ${credsBlock(x)}
  ${studioBlock(x)}
  ${contactBlock(x)}`;
}

/* ---- render & events ---- */
const curTalent=()=>ROUTE.startsWith("talent:")?TALENTS.find(v=>v.slug===ROUTE.slice(7)):null;
function render(){
  const app=document.getElementById("app");
  let nav="home";
  if(ROUTE.startsWith("talent:")){const x=curTalent();app.innerHTML=x?viewTalent(x):viewNotFound();nav="talents";if(x)document.title=x.name+" · KBBI Voice Talent"}
  else if(ROUTE==="notfound"){app.innerHTML=viewNotFound()}
  else{app.innerHTML=viewHome();if(location.hash==="#talents")nav="talents";if(location.hash==="#how")nav="how"}
  document.querySelectorAll("nav.main a").forEach(a=>{if(a.dataset.route===nav)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current")});
}
function applyLang(){
  document.documentElement.lang=lang==="zh"?"zh-Hans":lang;
  document.querySelectorAll("[data-i]").forEach(el=>{el.textContent=t(el.dataset.i)});
  document.querySelectorAll(".lang button").forEach(b=>b.setAttribute("aria-pressed",b.dataset.lang===lang));
  render();
}
function toast(msg){const el=document.createElement("div");el.className="toast";el.setAttribute("role","status");el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),2200)}

document.querySelector(".lang").addEventListener("click",e=>{
  const b=e.target.closest("button[data-lang]");if(!b)return;
  lang=b.dataset.lang;
  try{localStorage.setItem("kbbi-lang",lang)}catch(err){/* storage blocked: language resets next visit */}
  applyLang();
});
document.getElementById("app").addEventListener("click",e=>{
  const x=curTalent();
  const tg=e.target.closest("[data-tag]");
  if(tg){tagFilter=tg.dataset.tag;document.getElementById("roster").innerHTML=rosterBlock();return}
  const ct=e.target.closest("[data-cat]");
  if(ct&&x){catFilter=ct.dataset.cat;document.getElementById("pf").innerHTML=portfolioBlock(x);return}
  if(e.target.closest("[data-reel]")&&x){openMedia(t("demoH")+" · "+x.name,x.reel.url);return}
  const sc=e.target.closest("[data-scroll]");
  if(sc){const el=document.getElementById(sc.dataset.scroll);if(el)el.scrollIntoView({behavior:"smooth"});return}
  const sp=e.target.closest("[data-sample]");
  if(sp&&x){const s=x.samples[+sp.dataset.sample];if(s)openMedia(x.name+" · "+(s.raw?t("rawT"):L(s.title)),s.url);return}
  const vd=e.target.closest("[data-video]");
  if(vd&&x){const v=x.videos[+vd.dataset.video];if(v)openMedia(x.name+" · "+t("video")+" "+(+vd.dataset.video+1),v.url);return}
  const wk=e.target.closest("[data-work]");
  if(wk&&x){const w=x.works[+wk.dataset.work];if(w)openMedia(titleOf(w),w.link);return}
  const cp=e.target.closest("[data-copy]");
  if(cp){
    const text=cp.dataset.copy==="link"?location.origin+location.pathname:cp.dataset.copy;
    const ok=()=>toast(cp.dataset.copy==="link"?t("copied"):"✓ "+text);
    if(navigator.clipboard)navigator.clipboard.writeText(text).then(ok,()=>toast(t("copyFail")));else toast(t("copyFail"));
  }
});
document.getElementById("player").addEventListener("click",e=>{if(e.target===e.currentTarget||e.target.closest("[data-close]"))closePlayer()});
document.getElementById("player").addEventListener("close",()=>{document.getElementById("player").innerHTML=""});
window.addEventListener("hashchange",()=>{if(ROUTE==="home")render()});
applyLang();
if(location.hash){const el=document.getElementById(location.hash.slice(1));if(el)el.scrollIntoView()}
